package cn.zhuatech.qualityagent.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class CapaRecommendationReleaseServiceTest{private final CapaRecommendationReleaseService s=new CapaRecommendationReleaseService();@Test void releasesControlledCapa(){var r=s.assess(new CapaRecommendationReleaseService.Request("C1",true,true,true,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(CapaRecommendationReleaseService.Decision.RELEASE);}@Test void reviewsEffectivenessAndAudit(){var r=s.assess(new CapaRecommendationReleaseService.Request("C2",true,true,true,true,true,true,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksWeakCapa(){var r=s.assess(new CapaRecommendationReleaseService.Request("C3",false,false,false,false,false,false,true,true,false));assertThat(r.blockers()).hasSize(7);}}
